		return Org{}, ErrNotFound
	}
	if err := f(&o); err != nil {
		return Org{}, err
	}
	o.ID = id
	if err := checkOrg(o); err != nil {
		return Org{}, err
	}
	s.orgs[id] = o
	return o, nil
