import (
	"encoding/json"
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"time"

	"example.com/tally/internal/money"
	"example.com/tally/internal/store"
)

// Version is the version Save writes.
const Version = 3

// ErrUnsupportedVersion is returned for a file of a version Load cannot read.
var ErrUnsupportedVersion = errors.New("unsupported snapshot version")

type fileV2 struct {
	Version int         `json:"version"`
	SavedAt time.Time   `json:"saved_at"`
	State   store.State `json:"state"`
}

// Version 3 keeps the invoice numbers and each organization's next number in the state.
type fileV3 = fileV2

// Save writes everything in st to path. The file is replaced atomically: a crash leaves either the old snapshot or the
// new one at path.
func Save(st *store.Store, path string, now time.Time) error {
	b, err := json.MarshalIndent(fileV3{Version: Version, SavedAt: now.UTC(), State: st.Export()}, "", "  ")
	if err != nil {
		return err
	}
	return writeFile(path, append(b, '\n'))
}

// Load reads a snapshot written by Save, or by an older version of Tally, and returns a store holding it.
func Load(path string) (*store.Store, error) {
	b, err := os.ReadFile(path)
	if err != nil {
		return nil, err
	}
	st, _, err := parse(b, path)
	if err != nil {
		return nil, err
	}
	return store.FromState(st)
}

// Upgrade rewrites the snapshot at path as the current version. A file of an older version is first copied byte for
// byte to "<path>.v<old version>.bak". A file of the current version is left alone, without a backup. A file of a
// version Load cannot read fails with ErrUnsupportedVersion and is left untouched.
func Upgrade(path string) error {
	b, err := os.ReadFile(path)
	if err != nil {
		return err
	}
	st, version, err := parse(b, path)
	if err != nil {
		return err
	}
	if version == Version {
		return nil
	}
	if err := writeFile(fmt.Sprintf("%s.v%d.bak", path, version), b); err != nil {
		return fmt.Errorf("snapshot %s: backup: %w", path, err)
	}
	s, err := store.FromState(st)
	if err != nil {
		return fmt.Errorf("snapshot %s: %w", path, err)
	}
	return Save(s, path, time.Now())
}

// parse reads the state of a snapshot of any version Load can read, and returns the version it was written as.
func parse(b []byte, path string) (store.State, int, error) {
	var head struct {
		Version int `json:"version"`
	}
	if err := json.Unmarshal(b, &head); err != nil {
		return store.State{}, 0, fmt.Errorf("snapshot %s: %w", path, err)
	}
	switch head.Version {
	case 1:
		st, err := migrateV1(b)
		if err != nil {
			return store.State{}, 0, fmt.Errorf("snapshot %s: version 1: %w", path, err)
		}
		return st, 1, nil
	case 2, 3:
		var f fileV3
		if err := json.Unmarshal(b, &f); err != nil {
			return store.State{}, 0, fmt.Errorf("snapshot %s: %w", path, err)
		}
		return f.State, head.Version, nil
	default:
		return store.State{}, 0, fmt.Errorf("snapshot %s: %w %d", path, ErrUnsupportedVersion, head.Version)
	}
}

// writeFile replaces path with data. It writes a temporary file in the same folder, flushes it to disk and renames it
// over path, so path always holds either the old contents or the whole new ones. The temporary file is removed on failure.
func writeFile(path string, data []byte) (err error) {
	f, err := os.CreateTemp(filepath.Dir(path), filepath.Base(path)+".tmp-*")
	if err != nil {
		return err
	}
	defer func() {
		if err != nil {
			_ = f.Close()
			_ = os.Remove(f.Name())
		}
	}()
	if _, err = f.Write(data); err != nil {
		return err
	}
	if err = f.Sync(); err != nil {
		return err
	}
	if err = f.Close(); err != nil {
		return err
	}
	return os.Rename(f.Name(), path)
}

