func newInvoice(orgID, customerID string) store.Invoice {
	return store.Invoice{OrgID: orgID, CustomerID: customerID, Currency: money.EUR, Lines: []store.Line{{Description: "x", Quantity: 1, UnitAmount: 100}}}
}

// writeVersion2 writes st in the layout of version 2, which had no invoice numbers.
func writeVersion2(t *testing.T, st *store.Store, path string) {
	t.Helper()
	s := st.Export()
	s.NextInvoiceNumbers = nil
	for i := range s.Invoices {
		s.Invoices[i].Number = ""
	}
	b, err := json.Marshal(file{Version: 2, SavedAt: time.Date(2026, 2, 1, 12, 0, 0, 0, time.UTC), State: s})
	if err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(path, b, 0o600); err != nil {
		t.Fatal(err)
	}
}

func versionOf(t *testing.T, path string) int {
	t.Helper()
	b, err := os.ReadFile(path)
	if err != nil {
		t.Fatal(err)
	}
	var head struct {
		Version int `json:"version"`
	}
	if err := json.Unmarshal(b, &head); err != nil {
		t.Fatal(err)
	}
	return head.Version
}

func TestSaveWritesVersion3WithoutTempFiles(t *testing.T) {
	now := time.Date(2026, 2, 1, 12, 0, 0, 0, time.UTC)
	dir := t.TempDir()
	path := filepath.Join(dir, "tally.json")
	for range 2 {
		if err := Save(store.New(), path, now); err != nil {
			t.Fatal(err)
		}
	}
	if v := versionOf(t, path); v != 3 {
		t.Fatalf("version = %d, want 3", v)
	}
	entries, err := os.ReadDir(dir)
	if err != nil {
		t.Fatal(err)
	}
	if len(entries) != 1 {
		t.Fatalf("the folder holds %d files, want only the snapshot", len(entries))
	}
}

func TestLoadNumbersInvoicesOfOlderFiles(t *testing.T) {
	t0 := time.Date(2026, 2, 1, 12, 0, 0, 0, time.UTC)
	st := store.New()
	o, _ := st.CreateOrg("A", store.OrgTeam, "UTC", 0, t0)
	other, _ := st.CreateOrg("B", store.OrgTeam, "UTC", 0, t0)
	c, _ := st.CreateCustomer(o.ID, "Jane", "jane@example.com", t0)
	oc, _ := st.CreateCustomer(other.ID, "John", "john@example.com", t0)
	// The later invoice is stored first, so creation order differs from ID order.
	late, _ := st.CreateInvoice(newInvoice(o.ID, c.ID), t0.Add(time.Hour))
	early, _ := st.CreateInvoice(newInvoice(o.ID, c.ID), t0)
	foreign, _ := st.CreateInvoice(newInvoice(other.ID, oc.ID), t0.Add(2*time.Hour))

	path := filepath.Join(t.TempDir(), "tally.json")
	writeVersion2(t, st, path)
	got, err := Load(path)
	if err != nil {
		t.Fatal(err)
	}
	for _, tc := range []struct{ orgID, invID, want string }{
		{o.ID, early.ID, "INV-000001"},
		{o.ID, late.ID, "INV-000002"},
		{other.ID, foreign.ID, "INV-000001"},
	} {
		inv, ok := got.Invoice(tc.orgID, tc.invID)
		if !ok || inv.Number != tc.want {
			t.Fatalf("invoice %s number = %q, want %s", tc.invID, inv.Number, tc.want)
		}
	}
	next, err := got.CreateInvoice(newInvoice(o.ID, c.ID), t0)
	if err != nil || next.Number != "INV-000003" {
		t.Fatalf("next number = %q (%v), want INV-000003", next.Number, err)
	}
}

func TestUpgradeBacksUpOlderFile(t *testing.T) {
	st := store.New()
	o, _ := st.CreateOrg("A", store.OrgTeam, "UTC", 0, time.Now())
	c, _ := st.CreateCustomer(o.ID, "Jane", "jane@example.com", time.Now())
	_, _ = st.CreateInvoice(newInvoice(o.ID, c.ID), time.Now())
	path := filepath.Join(t.TempDir(), "tally.json")
	writeVersion2(t, st, path)
	orig, err := os.ReadFile(path)
	if err != nil {
		t.Fatal(err)
	}

	if err := Upgrade(path); err != nil {
		t.Fatal(err)
	}
	bak, err := os.ReadFile(path + ".v2.bak")
	if err != nil || !bytes.Equal(bak, orig) {
		t.Fatalf("the backup is not a copy of the original: %v", err)
	}
	if v := versionOf(t, path); v != 3 {
		t.Fatalf("version after Upgrade = %d, want 3", v)
	}
	got, err := Load(path)
	if err != nil {
		t.Fatal(err)
	}
	if inv, ok := got.Invoice(o.ID, store.Invoice{}.ID); ok || inv.Number != "" {
		t.Fatal("unexpected invoice")
	}
	if list := got.ListInvoices(o.ID, store.InvoiceFilter{}); len(list) != 1 || list[0].Number != "INV-000001" {
		t.Fatalf("invoices after Upgrade = %+v", list)
	}
}

func TestUpgradeVersion1(t *testing.T) {
	orig, err := os.ReadFile(filepath.Join("testdata", "v1.json"))
	if err != nil {
		t.Fatal(err)
	}
	path := filepath.Join(t.TempDir(), "tally.json")
	if err := os.WriteFile(path, orig, 0o600); err != nil {
		t.Fatal(err)
	}
	if err := Upgrade(path); err != nil {
		t.Fatal(err)
	}
	if bak, err := os.ReadFile(path + ".v1.bak"); err != nil || !bytes.Equal(bak, orig) {
		t.Fatalf("the backup is not a copy of the original: %v", err)
	}
	if v := versionOf(t, path); v != 3 {
		t.Fatalf("version after Upgrade = %d, want 3", v)
	}
	if _, err := Load(path); err != nil {
		t.Fatal(err)
	}
}

func TestUpgradeLeavesCurrentFileAlone(t *testing.T) {
	path := filepath.Join(t.TempDir(), "tally.json")
	if err := Save(store.New(), path, time.Now()); err != nil {
		t.Fatal(err)
	}
	orig, _ := os.ReadFile(path)
	if err := Upgrade(path); err != nil {
		t.Fatal(err)
	}
	if after, _ := os.ReadFile(path); !bytes.Equal(after, orig) {
		t.Fatal("Upgrade changed a version 3 file")
	}
	if _, err := os.Stat(path + ".v3.bak"); !errors.Is(err, os.ErrNotExist) {
		t.Fatalf("a version 3 file got a backup: %v", err)
	}
}

func TestUpgradeRefusesFutureVersions(t *testing.T) {
	path := filepath.Join(t.TempDir(), "tally.json")
	orig := []byte(`{"version": 4, "state": {}}`)
	if err := os.WriteFile(path, orig, 0o600); err != nil {
		t.Fatal(err)
	}
	if err := Upgrade(path); !errors.Is(err, ErrUnsupportedVersion) {
		t.Fatalf("err = %v", err)
	}
	if _, err := Load(path); !errors.Is(err, ErrUnsupportedVersion) {
		t.Fatalf("Load err = %v", err)
	}
	if after, _ := os.ReadFile(path); !bytes.Equal(after, orig) {
		t.Fatal("Upgrade changed a file it refused")
	}
	if _, err := os.Stat(path + ".v4.bak"); !errors.Is(err, os.ErrNotExist) {
		t.Fatalf("a refused file got a backup: %v", err)
	}
}
